import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, abort, send_file, jsonify

app = Flask(__name__)

BASE_DIR = os.environ.get('DOCUMENT_ROOT', '/srv/documents')
API_KEY_HASH = os.environ.get('API_KEY_HASH', '')
BLOCKED_EXTENSIONS = {'.exe', '.sh', '.bat', '.cmd', '.ps1'}
MAX_PATH_DEPTH = 5

def verify_api_key(provided_key):
    """Verify API key using constant-time comparison."""
    if not provided_key or not API_KEY_HASH:
        return False
    key_hash = hashlib.sha256(provided_key.encode('utf-8')).hexdigest()
    return hmac.compare_digest(key_hash, API_KEY_HASH)

def is_path_safe(requested_path):
    """Check if the requested path is safe (no traversal)."""
    # Reject null bytes
    if '\x00' in requested_path:
        return False
    # Reject obvious traversal patterns
    if '..' in requested_path:
        return False
    # Check path depth
    parts = PurePosixPath(requested_path).parts
    if len(parts) > MAX_PATH_DEPTH:
        return False
    # Check for blocked extensions
    ext = PurePosixPath(requested_path).suffix.lower()
    if ext in BLOCKED_EXTENSIONS:
        return False
    # Reject absolute paths
    if requested_path.startswith('/'):
        return False
    return True

def sanitize_filename(filename):
    """Remove control characters and normalize whitespace."""
    cleaned = ''.join(c for c in filename if unicodedata.category(c)[0] != 'C')
    return cleaned.strip()

def resolve_document_path(user_path):
    """Resolve the final filesystem path for a document request."""
    # Step 1: Sanitize the filename (remove control chars)
    sanitized = sanitize_filename(user_path)
    # Step 2: Security validation on sanitized path
    if not is_path_safe(sanitized):
        return None
    # Step 3: Unicode NFC normalization for consistent filesystem access
    normalized = unicodedata.normalize('NFC', sanitized)
    # Step 4: Construct full path
    full_path = os.path.join(BASE_DIR, normalized)
    # Step 5: Verify the resolved path is within BASE_DIR
    real_path = os.path.realpath(full_path)
    base_real = os.path.realpath(BASE_DIR)
    if not real_path.startswith(base_real + os.sep) and real_path != base_real:
        return None
    return real_path

@app.route('/api/documents/<path:filepath>', methods=['GET'])
def get_document(filepath):
    """Serve a document from the document root."""
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        abort(401)
    resolved = resolve_document_path(filepath)
    if resolved is None:
        abort(404)
    if not os.path.isfile(resolved):
        abort(404)
    return send_file(resolved)

@app.route('/api/documents', methods=['GET'])
def list_documents():
    """List available documents."""
    api_key = request.headers.get('X-API-Key', '')
    if not verify_api_key(api_key):
        abort(401)
    subdir = request.args.get('dir', '')
    resolved = resolve_document_path(subdir) if subdir else os.path.realpath(BASE_DIR)
    if resolved is None:
        abort(404)
    if not os.path.isdir(resolved):
        abort(404)
    files = []
    for entry in os.scandir(resolved):
        files.append({'name': entry.name, 'is_dir': entry.is_dir(), 'size': entry.stat().st_size if entry.is_file() else 0})
    return jsonify(files)

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
